def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()


def get_current_user(token: str = Depends(oauth2_scheme), db: Session = Depends(get_db)):
    payload = decode_access_token(token)

    if payload is None:
        raise HTTPException(status_code=401, detail="Ungültiger Token")

    username = payload.get("sub")
    user = db.query(models.User).filter(models.User.username == username).first()

    if user is None:
        raise HTTPException(status_code=401, detail="User nicht gefunden")

    return user


def require_authenticated_user(
    current_user: models.User = Depends(get_current_user),
):
    if current_user.role not in ["developer", "operator", "user"]:
        raise HTTPException(status_code=403, detail="Keine Berechtigung")
    return current_user

def require_operator_or_developer(
    current_user: models.User = Depends(get_current_user),
):
    if current_user.role not in ["developer", "operator"]:
        raise HTTPException(status_code=403, detail="Keine Berechtigung")
    return current_user


def require_developer(
    current_user: models.User = Depends(get_current_user),
):
    if current_user.role != "developer":
        raise HTTPException(status_code=403, detail="Developer-Zugriff erforderlich")
    return current_user


def calculate_place_status_for_range(
    place: models.Place,
    bookings: list[models.Booking],
    start_date: date,
    end_date: date,
):
    if start_date > end_date:
        raise HTTPException(status_code=400, detail="start_date must be before or equal to end_date")

    if place.type == "Dauercamper":
        return {
            "id": place.id,
            "name": place.name,
            "type": place.type,
            "capacity": place.capacity,
            "length_m": place.length_m,
            "price_per_night": place.price_per_night,
            "start_date": start_date,
            "end_date": end_date,
            "max_occupancy": 0,
            "occupied_days": 0,
            "fully_booked_days": 0,
            "status": "gray",
        }

    if place.type == "Gesperrt":
        return {
            "id": place.id,
            "name": place.name,
            "type": place.type,
            "capacity": place.capacity,
            "length_m": place.length_m,
            "price_per_night": place.price_per_night,
            "start_date": start_date,
            "end_date": end_date,
            "max_occupancy": 0,
            "occupied_days": 0,
            "fully_booked_days": 0,
            "status": "blocked",
        }
    total_days = (end_date - start_date).days + 1
    max_occupancy = 0
    occupied_days = 0
    fully_booked_days = 0

    for day_offset in range(total_days):
        current_day = start_date + timedelta(days=day_offset)

        occupancy = 0

        for booking in bookings:
            if booking.start_date <= current_day < booking.end_date:
                if place.type == "Zeltwiese":
                    occupancy += booking.tent_count or 1
                else:
                    occupancy += 1

        if occupancy > 0:
            occupied_days += 1

        if occupancy >= place.capacity:
            fully_booked_days += 1

        if occupancy > max_occupancy:
            max_occupancy = occupancy

    if occupied_days == 0:
        status = "green"
    elif fully_booked_days > 0:
        status = "red"
    else:
        status = "yellow"

    return {
        "id": place.id,
        "name": place.name,
        "type": place.type,
        "capacity": place.capacity,
        "length_m": place.length_m,
        "price_per_night": place.price_per_night,
        "start_date": start_date,
        "end_date": end_date,
        "max_occupancy": max_occupancy,
        "occupied_days": occupied_days,
        "fully_booked_days": fully_booked_days,
        "status": status,
    }

def would_exceed_capacity(
    place: models.Place,
    existing_bookings: list[models.Booking],
    start_date: date,
    end_date: date,
    requested_units: int = 1,
) -> bool:
    total_days = (end_date - start_date).days

    for day_offset in range(total_days):
        current_day = start_date + timedelta(days=day_offset)
        occupancy = 0

        for existing_booking in existing_bookings:
            if (
                existing_booking.start_date
                <= current_day
                < existing_booking.end_date
            ):
                if place.type == "Zeltwiese":
                    occupancy += existing_booking.tent_count or 1
                else:
                    occupancy += 1

        if occupancy + requested_units > place.capacity:
            return True

    return False

