import type { Place, Booking, PlaceStatus, User, LoginResponse, CurrentUser, BookingReceipt, BookingQuote, Tariff } from "../types";

const API_BASE_URL = import.meta.env.VITE_API_BASE_URL || "/api";

function getAuthToken() {
  return localStorage.getItem("auth_token");
}

async function apiGet<T>(path: string): Promise<T> {
  const token = getAuthToken();

  const res = await fetch(`${API_BASE_URL}${path}`, {
    headers: token
      ? {
          Authorization: `Bearer ${token}`,
        }
      : undefined,
  });

  if (!res.ok) {
    const errorData = await res.json().catch(() => ({}));
    throw new Error(errorData.detail || "Unbekannter Fehler");
  }

  return res.json();
}

export async function login(username: string, password: string): Promise<LoginResponse> {
  const body = new URLSearchParams();
  body.append("username", username);
  body.append("password", password);

  const res = await fetch(`${API_BASE_URL}/login`, {
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body: body.toString(),
  });

  if (!res.ok) {
    const errorData = await res.json().catch(() => ({}));
    throw new Error(errorData.detail || "Login fehlgeschlagen");
  }

  return res.json() as Promise<LoginResponse>;
}

export async function fetchAvailablePlaces(
  startDate: string,
  endDate: string,
  vehicleLengthM?: number
): Promise<Place[]> {
  const params = new URLSearchParams({
    start_date: startDate,
    end_date: endDate,
  });

  if (vehicleLengthM !== undefined && vehicleLengthM > 0) {
    params.set("vehicle_length_m", String(vehicleLengthM));
  }

  return apiGet<Place[]>(`/places/available?${params.toString()}`);
}

export async function markNoShow(bookingId: number) {
  const token = getAuthToken();

  const res = await fetch(`${API_BASE_URL}/bookings/${bookingId}/noshow`, {
    method: "PUT",
    headers: token
      ? {
          Authorization: `Bearer ${token}`,
        }
      : undefined,
  });

  if (!res.ok) {
    const errorData = await res.json().catch(() => ({}));
    throw new Error(
      errorData.detail || "Fehler beim Setzen von 'nicht erschienen'"
    );
  }

  return res.json();
}

