export async function createBooking(data: {
  place_id: number;
  start_date: string;
  end_date: string;
  guest_name: string;
  guest_street?: string;
  guest_postal_code?: string;
  guest_city?: string;
  people_count?: number;
  adult_count?: number;
  child_count?: number;
  day_visitor_count?: number;
  has_electricity?: boolean;
  has_waste?: boolean;
  has_rhine_view?: boolean;
  dog_count?: number;
  car_count?: number;
  motorcycle_count?: number;
  camper_count?: number;
  camper_length_m?: number | null;
  tent_tariff_code?: string | null;
  place_price_per_night?: number | null;
  vehicle_size: string;
  tent_count?: number | null;
  notes: string;
}) {
  const token = getAuthToken();

  const res = await fetch(`${API_BASE_URL}/bookings`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    body: JSON.stringify(data),
  });

  if (!res.ok) {
    const errorData = await res.json().catch(() => ({}));
    throw new Error(errorData.detail || "Fehler beim Erstellen der Buchung");
  }

  return res.json();
}

